<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Senate\ProfileExaminationDispositionAuthorityOpeningService;
use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:open-profile-examination-disposition-authority',description:'Open one bounded Profile examination disposition authority')]
final class SenateOpenProfileExaminationDispositionAuthorityCommand extends Command{public function __construct(private readonly ProfileExaminationDispositionAuthorityOpeningService $service){parent::__construct();}protected function configure():void{$this->addArgument('reconciliation-id',InputArgument::REQUIRED)->addArgument('lord-speaker-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$record=$this->service->open((string)$input->getArgument('reconciliation-id'),(string)$input->getArgument('lord-speaker-binding-id'));}catch(\Throwable $exception){$output->writeln('<error>REFUSED</error> '.$exception->getMessage());return self::FAILURE;}$output->writeln($input->getOption('json')?json_encode($record,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>PROFILE_EXAMINATION_DISPOSITION_AUTHORITY_OPENED</info> '.$record['opening_id']);return self::SUCCESS;}}
